ULL AND set_id=ANY(ARRAY['8063eabc-362a-4f15-a4ec-4ed73824252d','9fa08d47-d2cd-4829-85b6-819692a6850a','12f2bb10-ec15-4783-bc9b-c946546a1abc']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['3c83ecfe-306a-4f64-8003-e455fb4be4f9','aec39508-e7ed-4d3d-a876-51dc5f7c258e','db02f454-b7b4-497d-b2a0-a9e5ab074665','bd47b01b-2694-4e7a-a446-9c2f7a5cbba7']::uuid[]) OR variant_id=ANY(ARRAY['e2710b68-93f0-4cdd-8537-57a1e6046a0f','41385d11-8aac-4618-b8b0-b810bdfcaa8a','1f58b1ed-c5fe-4d9b-9d05-a3f3cc24cd2e','d782e5b3-f7f7-4ac9-84ff-c9c6dfa05aca']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['3c83ecfe-306a-4f64-8003-e455fb4be4f9','aec39508-e7ed-4d3d-a876-51dc5f7c258e','db02f454-b7b4-497d-b2a0-a9e5ab074665','bd47b01b-2694-4e7a-a446-9c2f7a5cbba7']::uuid[]) OR variant_id=ANY(ARRAY['e2710b68-93f0-4cdd-8537-57a1e6046a0f','41385d11-8aac-4618-b8b0-b810bdfcaa8a','1f58b1ed-c5fe-4d9b-9d05-a3f3cc24cd2e','d782e5b3-f7f7-4ac9-84ff-c9c6dfa05aca']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['8063eabc-362a-4f15-a4ec-4ed73824252d','9fa08d47-d2cd-4829-85b6-819692a6850a','12f2bb10-ec15-4783-bc9b-c946546a1abc']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['8063eabc-362a-4f15-a4ec-4ed73824252d','9fa08d47-d2cd-4829-85b6-819692a6850a','12f2bb10-ec15-4783-bc9b-c946546a1abc']::uuid[])) ORDER BY scope,identity;